const body = $input.first().json.body || $input.first().json;

function clean(value) {
  return String(value || '').trim();
}

function sql(value) {
  return clean(value).replace(/'/g, "''");
}

const dueno = clean(body.dueno);
const partesNombre = dueno.split(/\s+/).filter(Boolean);
const nombres = partesNombre.length > 1 ? partesNombre.slice(0, -1).join(' ') : dueno;
const apellidos = partesNombre.length > 1 ? partesNombre.slice(-1).join(' ') : 'Sin apellido';
const email = clean(body.email).toLowerCase();
const telefono = clean(body.telefono);
const clienteWhere = email ? `email = '${sql(email)}'` : `telefono = '${sql(telefono)}'`;

const tipoEntrada = clean(body.tipo_caso || body.tipo || 'Consulta general');
const tipo = tipoEntrada === 'Vacunacion' ? 'Vacunación' : tipoEntrada;
const observaciones = clean(body.observaciones || body.obs);
const hora = clean(body.hora).slice(0, 5);

const prioridades = {
  'Emergencia': 'Alta',
  'Consulta general': 'Media',
  'Vacunación': 'Baja'
};

const prioridad = body.prioridad || prioridades[tipo] || 'Media';
const disponible = true;
const accion = disponible ? 'Verificar cliente por email y confirmar' : 'Mostrar horarios alternativos';
const estado = body.estado || 'Confirmada';

return [{
  json: {
    dueno,
    nombres,
    apellidos,
    telefono,
    email,
    mascota: clean(body.mascota),
    especie: clean(body.especie),
    tipo_caso: tipo,
    prioridad,
    fecha: clean(body.fecha),
    hora,
    hora_formateada: body.hora_formateada || hora,
    verificacion_cliente: 'email',
    observaciones,
    accion_dmn: accion,
    estado,
    disponible,
    fecha_creacion: body.creado_en || new Date().toISOString(),
    sql_nombres: sql(nombres),
    sql_apellidos: sql(apellidos),
    sql_telefono: sql(telefono),
    sql_email: sql(email),
    sql_cliente_where: clienteWhere,
    sql_mascota: sql(body.mascota),
    sql_especie: sql(body.especie),
    sql_tipo_caso: sql(tipo),
    sql_prioridad: sql(prioridad),
    sql_fecha: sql(body.fecha),
    sql_hora: sql(hora),
    sql_estado: sql(estado),
    sql_accion_dmn: sql(accion),
    sql_observaciones: sql(observaciones)
  }
}];

