INSERT INTO clientes (nombres, apellidos, telefono, email)
SELECT '{{ $('Aplicar Reglas DMN').item.json.sql_nombres }}', '{{ $('Aplicar Reglas DMN').item.json.sql_apellidos }}', '{{ $('Aplicar Reglas DMN').item.json.sql_telefono }}', '{{ $('Aplicar Reglas DMN').item.json.sql_email }}'
WHERE NOT EXISTS (
  SELECT 1 FROM clientes WHERE {{ $('Aplicar Reglas DMN').item.json.sql_cliente_where }}
);
